import{c as r,Q as d,j as o,m as a}from"./chunks/framework.rWdQudnF.js";const c=JSON.parse('{"title":"架构师-备考 综合知识-系统工程-企业信息化","description":"","frontmatter":{"title":"架构师-备考 综合知识-系统工程-企业信息化"},"headers":[],"relativePath":"综合知识/系统工程/企业信息化.md","filePath":"综合知识/系统工程/企业信息化.md","lastUpdated":null}'),e={name:"综合知识/系统工程/企业信息化.md"};function n(s,t,h,l,g,i){return d(),o("div",null,[...t[0]||(t[0]=[a('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 企业数字化转型 5 个阶段</li><li>[x] 组织信息化需求 3 个层次（战略/运作/技术）</li><li>[x] 信息系统规划方法（CSF/SST/BSP）</li><li>[x] ERP 概念与 5 层计划</li><li>[x] 供应链信息流（需求/供应）</li><li>[x] 商业智能（BI）4 阶段</li><li>[x] 企业信息集成（内部/外部）+ 系统应用集成 4 层</li><li>[x] 电子商务实体</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、企业数字化转型" tabindex="-1">一、企业数字化转型 <a class="header-anchor" href="#一、企业数字化转型" aria-label="Permalink to &quot;一、企业数字化转型&quot;">​</a></h3><blockquote><p>企业数字化转型五个发展阶段：<strong>初始级 → 单元级 → 流程级 → 网络级 → 生态级</strong>。</p></blockquote><hr><h3 id="二、组织信息化需求-3-层次-★" tabindex="-1">二、组织信息化需求 3 层次 ★ <a class="header-anchor" href="#二、组织信息化需求-3-层次-★" aria-label="Permalink to &quot;二、组织信息化需求 3 层次 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层次</th><th>目标</th><th>内容</th></tr></thead><tbody><tr><td><strong>战略需求</strong></td><td>提升组织竞争能力，为可持续发展提供支持环境</td><td>最高层</td></tr><tr><td><strong>运作需求</strong></td><td>实现信息化战略目标、运营策略、人才培养</td><td>中间层</td></tr><tr><td><strong>技术需求</strong></td><td>在信息技术层面上对系统完善、升级、集成和整合</td><td>基础层</td></tr></tbody></table><blockquote><p>三个层次<strong>互有内在联系</strong>，并非相互孤立。信息化主体不是程序员和项目经理。</p></blockquote><hr><h3 id="三、信息系统规划方法-★" tabindex="-1">三、信息系统规划方法 ★ <a class="header-anchor" href="#三、信息系统规划方法-★" aria-label="Permalink to &quot;三、信息系统规划方法 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>核心思想</th><th>特点</th></tr></thead><tbody><tr><td><strong>关键成功因素法（CSF）</strong></td><td>识别关键成功因素 → 找出关键信息集合 → 确定系统开发<strong>优先次序</strong></td><td>通过目标分解 → CSF识别 → 产生数据字典</td></tr><tr><td><strong>战略目标集转化法（SST）</strong></td><td>将整个过程看成&quot;信息集合&quot;，组织战略目标 → MIS 战略目标</td><td>自上而下转化</td></tr><tr><td><strong>企业系统规划法（BSP）</strong></td><td><strong>自上而下</strong>识别企业目标/过程/数据，<strong>自下而上</strong>设计信息系统</td><td>先分析后设计</td></tr></tbody></table><hr><h3 id="四、erp-企业资源计划-★" tabindex="-1">四、ERP（企业资源计划）★ <a class="header-anchor" href="#四、erp-企业资源计划-★" aria-label="Permalink to &quot;四、ERP（企业资源计划）★&quot;">​</a></h3><blockquote><p>ERP 对企业的<strong>物流、资金流、信息流</strong>进行全面集成管理。</p></blockquote><p><strong>ERP 五个层次计划：</strong></p><table tabindex="0"><thead><tr><th>层次</th><th>说明</th></tr></thead><tbody><tr><td>经营计划</td><td>最高层，企业总体目标</td></tr><tr><td><strong>生产计划大纲</strong></td><td>根据经营计划生产目标制定，对经营计划的细化</td></tr><tr><td><strong>主生产计划</strong></td><td>说明生产什么、多少、何时交货，ERP 主要工作内容</td></tr><tr><td>物料需求计划</td><td>依据主生产计划计算物料需求</td></tr><tr><td><strong>能力需求计划</strong></td><td>尽早发现生产能力瓶颈，提供能力保障</td></tr><tr><td>车间作业计划</td><td>底层执行计划</td></tr></tbody></table><blockquote><p>ERP 中<strong>库存管理</strong>模块主要对企业物料的进、出、存进行管理。</p></blockquote><hr><h3 id="五、供应链信息流" tabindex="-1">五、供应链信息流 <a class="header-anchor" href="#五、供应链信息流" aria-label="Permalink to &quot;五、供应链信息流&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>方向</th><th>示例</th></tr></thead><tbody><tr><td><strong>需求信息流</strong></td><td>下游→上游</td><td>客户订单、销售报告、生产计划</td></tr><tr><td><strong>供应信息流</strong></td><td>上游→下游</td><td>库存记录、商品入库单、提货发运单、采购合同、完工报告单</td></tr></tbody></table><hr><h3 id="六、商业智能-bi-★" tabindex="-1">六、商业智能（BI）★ <a class="header-anchor" href="#六、商业智能-bi-★" aria-label="Permalink to &quot;六、商业智能（BI）★&quot;">​</a></h3><blockquote><p>BI 是企业对商业数据的搜集、管理和分析的系统过程。主要技术：<strong>数据仓库 + 联机分析处理 + 数据挖掘</strong>。</p></blockquote><p><strong>4 阶段处理过程：</strong></p><table tabindex="0"><thead><tr><th>阶段</th><th>内容</th><th>关键技术</th></tr></thead><tbody><tr><td><strong>1. 数据预处理</strong></td><td>实现企业原始数据的初步整合</td><td><strong>ETL</strong>（数据抽取、转换和装载）</td></tr><tr><td><strong>2. 建立数据仓库</strong></td><td>后续数据处理的基础</td><td>数据仓库</td></tr><tr><td><strong>3. 数据分析</strong></td><td>体现系统智能的关键</td><td><strong>OLAP</strong>（上卷/下钻/旋转分析）+ <strong>数据挖掘</strong>（建立模型预测趋势）</td></tr><tr><td><strong>4. 数据展现</strong></td><td>处理结果可视化</td><td>报表/仪表盘</td></tr></tbody></table><blockquote><p>OLAP 实现多维分析（上卷、下钻、旋转）；数据挖掘利用隐藏知识预测未来。</p></blockquote><hr><h3 id="七、企业信息集成" tabindex="-1">七、企业信息集成 <a class="header-anchor" href="#七、企业信息集成" aria-label="Permalink to &quot;七、企业信息集成&quot;">​</a></h3><p><strong>按组织范围分类：</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><strong>内部信息集成</strong></td><td>企业内部不同系统间的集成</td></tr><tr><td><strong>外部信息集成</strong></td><td>企业与外部合作伙伴的集成</td></tr></tbody></table><p><strong>按集成层次：</strong></p><table tabindex="0"><thead><tr><th>层次</th><th>功能</th></tr></thead><tbody><tr><td><strong>技术平台集成</strong></td><td>底层硬件/软件平台统一</td></tr><tr><td><strong>数据集成</strong></td><td>不同数据库系统间数据交换、互操作、分布数据管理、共享信息模型</td></tr><tr><td><strong>应用系统集成</strong></td><td>不同系统间实现互操作，数据和方法的共享</td></tr><tr><td><strong>业务过程集成</strong></td><td>跨系统的业务流程协调</td></tr></tbody></table><blockquote><p>系统应用集成基本原则是保证应用程序的<strong>互操作性</strong>。</p></blockquote><p><strong>系统应用集成 4 层服务（从底→顶）：</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">层次</th><th>服务</th></tr></thead><tbody><tr><td style="text-align:center;">4</td><td><strong>流程控制</strong>（最上层）</td></tr><tr><td style="text-align:center;">3</td><td>应用连接</td></tr><tr><td style="text-align:center;">2</td><td>信息传递与转化</td></tr><tr><td style="text-align:center;">1</td><td>通信（最底层）</td></tr></tbody></table><hr><h3 id="八、电子商务" tabindex="-1">八、电子商务 <a class="header-anchor" href="#八、电子商务" aria-label="Permalink to &quot;八、电子商务&quot;">​</a></h3><p><strong>参与实体</strong>：客户、商户、银行、认证中心。</p>',39)])])}const u=r(e,[["render",n]]);export{c as __pageData,u as default};
